def gen(rng):
    def fmt(ps):
        return str(len(ps)) + '\n' + '\n'.join(f'{a} {b}' for a, b in ps)

    def pair(lo, hi, maxlen):
        a = rng.randint(lo, hi - 1)
        b = min(hi, a + rng.randint(1, maxlen))
        return (a, b)

    tests = [fmt([(1, 2)]), fmt([(1, 2), (2, 3), (3, 4)]), fmt([(1, 5), (1, 5), (1, 5)]),
             fmt([(-5, 10), (-4, 8), (-3, 9)]), fmt([(1, 2), (3, 4), (5, 6), (7, 8)]),
             fmt([(-10 ** 6, 10 ** 6), (-10 ** 6, -999999), (999999, 10 ** 6)]),
             fmt([(1, 3), (2, 4), (3, 5), (4, 6)])]
    for n in (2, 3, 4, 5, 6, 7, 8, 9, 10):
        for _ in range(3):
            tests.append(fmt([pair(-10, 10, rng.choice((1, 3, 8))) for _ in range(n)]))
    tests.append(fmt([pair(-50, 50, 4) for _ in range(10)]))

    N = 100000
    tests.append(fmt([pair(-10 ** 6, 10 ** 6, 20) for _ in range(N)]))
    tests.append(fmt([pair(-10 ** 6, 10 ** 6, 10 ** 6) for _ in range(N)]))
    tests.append(fmt([(-10 ** 6 + 20 * i, -10 ** 6 + 20 * i + 10) for i in range(N)]))
    tests.append(fmt([(-i - 1, i + 1) for i in range(N)]))
    tests.append(fmt([pair(-1000, 1000, 5) for _ in range(N)]))
    return tests

